import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import axios from 'axios';

const Services = () => {
    const [menuOpen, setMenuOpen] = useState(false);
    const [services, setServices] = useState([]);
    const [loadingServices, setLoadingServices] = useState(true);

    // Booking Modal State
    const [selectedService, setSelectedService] = useState(null);
    const [selectedDate, setSelectedDate] = useState('');
    const [availableSlots, setAvailableSlots] = useState([]);
    const [selectedTime, setSelectedTime] = useState('');
    const [isBooking, setIsBooking] = useState(false);
    const [bookingError, setBookingError] = useState('');

    const navigate = useNavigate();
    const location = useLocation();

    useEffect(() => {
        const fetchServices = async () => {
            try {
                const token = localStorage.getItem('token');
                const res = await axios.get('http://localhost:5000/api/services', {
                    headers: { Authorization: `Bearer ${token}` }
                });
                setServices(res.data.data);
            } catch (err) {
                console.error("Failed to fetch services", err);
                setServices([]);
            } finally {
                setLoadingServices(false);
            }
        };
        fetchServices();
    }, []);

    const handleLogout = () => {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        navigate('/login');
    };

    const toggleMenu = () => setMenuOpen(!menuOpen);
    const isActive = (path) => location.pathname === path;

    // 1. When clicking "Get Appointment", open the modal and fetch slots
    const openBookingModal = async (service) => {
        setSelectedService(service);
        setSelectedTime('');
        setBookingError('');
        // Use today's date as default
        const today = new Date().toISOString().split('T')[0];
        setSelectedDate(today);
        await fetchSlots(service._id, today);
    };

    // 2. Fetch available slots for selected date
    const fetchSlots = async (serviceId, date) => {
        try {
            const token = localStorage.getItem('token');
            const res = await axios.get(`http://localhost:5000/api/appointments/available?serviceId=${serviceId}&date=${date}`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setAvailableSlots(res.data.availableSlots);
            setSelectedTime(''); // Reset time when date changes
        } catch (err) {
            console.error("Error fetching slots", err);
            setAvailableSlots([]);
            setBookingError("Failed to load available slots.");
        }
    };

    // 3. Handle date change
    const handleDateChange = (e) => {
        const newDate = e.target.value;
        setSelectedDate(newDate);
        fetchSlots(selectedService._id, newDate);
    };

    // 4. Confirm the booking
    const handleConfirmBooking = async () => {
        if (!selectedDate || !selectedTime) {
            setBookingError("Please choose a date AND an available time slot.");
            return;
        }

        setIsBooking(true);
        setBookingError('');

        try {
            const token = localStorage.getItem('token');
            const endTime = calculateEndTime(selectedTime, selectedService.duration);

            await axios.post('http://localhost:5000/api/appointments', {
                serviceId: selectedService._id,
                appointmentDate: selectedDate,
                startTime: selectedTime,
                endTime: endTime,
                notes: ""
            }, {
                headers: { Authorization: `Bearer ${token}` }
            });

            alert(`✅ ${selectedService.name} booked for ${selectedDate} at ${selectedTime}!`);
            setSelectedService(null); // Close modal
        } catch (error) {
            console.error("Booking Error:", error.response?.data || error.message);
            setBookingError("Failed to book. This slot may have just been taken. Please pick another.");
            // Refresh slots
            fetchSlots(selectedService._id, selectedDate);
        } finally {
            setIsBooking(false);
        }
    };

    // 5. Helper to calculate end time based on duration
    const calculateEndTime = (startTime, durationMinutes) => {
        const [hours, minutes] = startTime.split(':').map(Number);
        const totalMinutes = hours * 60 + minutes + durationMinutes;
        const endHours = Math.floor(totalMinutes / 60) % 24;
        const endMins = totalMinutes % 60;
        return `${String(endHours).padStart(2, '0')}:${String(endMins).padStart(2, '0')}`;
    };

    return (
        <div className="services-page">
            <nav className="services-navbar">
                <div className="nav-logo">BeautyBook</div>
                <div className="hamburger" onClick={toggleMenu}>☰</div>
                <div className="nav-links desktop-nav">
                    <span className={`nav-item ${isActive('/services') ? 'active' : ''}`}>🌸 Beauty treatments</span>
                    <span className={`nav-item ${isActive('/appointments') ? 'active' : ''}`} onClick={() => navigate('/appointments')}>📅 Appointment</span>
                    <span className="nav-icon">🔔</span>
                    <span className="nav-icon" onClick={handleLogout} style={{cursor: 'pointer'}}>⚙️</span>
                </div>
            </nav>

            <div className={`mobile-menu ${menuOpen ? 'open' : ''}`}>
                <div className="mobile-menu-content">
                    <span className={`mobile-nav-item ${isActive('/services') ? 'active' : ''}`}>🌸 Beauty treatments</span>
                    <span className={`mobile-nav-item ${isActive('/appointments') ? 'active' : ''}`} onClick={() => { setMenuOpen(false); navigate('/appointments'); }}>📅 Appointment</span>
                    <div className="mobile-nav-icons">
                        <span className="nav-icon">🔔</span>
                        <span className="nav-icon" onClick={handleLogout} style={{cursor: 'pointer'}}>⚙️</span>
                    </div>
                </div>
            </div>

            <div className="services-grid-container">
                <div className="services-grid">
                    {loadingServices ? (
                        <div className="loading">Loading services...</div>
                    ) : services.length === 0 ? (
                        <div className="empty-services">No services available.</div>
                    ) : (
                        services.map((service) => (
                            <div key={service._id} className="service-card">
                                <div className="service-image-wrapper">
                                    <img src={service.image} alt={service.name} className="service-image" />
                                </div>
                                <h3 className="service-title">{service.name}</h3>
                                <div className="service-details">
                                    <span>Durée: {service.duration} min</span>
                                    <span>Prix: {service.price} DA</span>
                                </div>
                                <button 
                                    className="service-btn" 
                                    onClick={() => openBookingModal(service)}
                                >
                                    Get Appointment
                                </button>
                            </div>
                        ))
                    )}
                </div>
            </div>

            {/* --- BOOKING MODAL --- */}
            {selectedService && (
                <div className="booking-modal-overlay" onClick={() => setSelectedService(null)}>
                    <div className="booking-modal" onClick={(e) => e.stopPropagation()}>
                        <h3 className="modal-title">Book: {selectedService.name}</h3>

                        <label>Choose a Date:</label>
                        <input 
                            type="date" 
                            value={selectedDate} 
                            onChange={handleDateChange}
                            min={new Date().toISOString().split('T')[0]}
                            className="date-input"
                        />

                        <label>Available Time Slots:</label>
                        <div className="slots-container">
                            {availableSlots.length === 0 ? (
                                <p className="no-slots">No available slots for this date.</p>
                            ) : (
                                availableSlots.map((slot) => (
                                    <button
                                        key={slot}
                                        className={`slot-btn ${selectedTime === slot ? 'selected' : ''}`}
                                        onClick={() => setSelectedTime(slot)}
                                    >
                                        {slot}
                                    </button>
                                ))
                            )}
                        </div>

                        {bookingError && <p className="booking-error">{bookingError}</p>}

                        <div className="modal-actions">
                            <button className="cancel-modal-btn" onClick={() => setSelectedService(null)}>Cancel</button>
                            <button 
                                className="confirm-booking-btn" 
                                onClick={handleConfirmBooking}
                                disabled={isBooking || !selectedTime}
                            >
                                {isBooking ? 'Booking...' : 'Confirm Appointment'}
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Services;
